/* Start GameLoadingView styles */

.cp-loading-logo-img{
	background: url(../../images/desktop/brand/loading_brand_logo.png) no-repeat center center;
	background-size: contain;
}

.cp-loading-view-desktop {
    background-image: url(../../images/desktop/brand/loading_background.png);
}

.cp-loading-brand-big {
	background-image: url(../../images/desktop/brand/loading_brand_logo.png);
}

.progressoverlay {
    background: url(../../images/desktop/brand/progress.png);
}

.gameByPlaytechWrapper>div {
	width: 300px;
	height: 28px;
	display: inline-block;
	margin: 0 15px 10px 0
}
.copyright-game .gameByPlaytechWrapper>div {
	background-image: url(../../images/desktop/brand/pt_proudly_presents_white.png);
}

.progressDiv {
	background-color: #ffffff;
	background: -webkit-linear-gradient(left, rgba(255,255,255,1) 0, rgba(255,255,255,1) 50%, rgba(255,255,255,1) 100%);
	background: linear-gradient(left, rgba(255,255,255,1) 0, rgba(255,255,255,1) 50%, rgba(255,255,255,1) 100%);
}
/* End GameLoadingView styles */
/*----------engagement dialogues----------*/
.engagement-dialog-button-container, .engagement-dialog-message-container {
	background-color: #0d395e;
	box-shadow: 0 4px 18px #0d395e;
}

.engagement-dialog-button {
	box-shadow: 0 4px 8px #0d395e;
}

.engagement-dialog-button.actionable {
	background-color: #6ecc8d;
	color: #ffffff;
}

.engagement-dialog-button.actionable:hover {
	background-color: #4da36a;
}

.engagement-dialog-button.cancel {
	background-color: #f66464;
	color: #1e1e1e;
}

.engagement-dialog-button.cancel:hover {
	background-color: #cb4141;
}

.engagement-dialog-message-container::-webkit-scrollbar-thumb {
	background: #70b7e5;
}

.engagement-dialog-message-container::-webkit-scrollbar-track {
	background-color: #0d395e;
}


/*----------toaster dialogues----------*/
.toaster_wrapper {
    background-color: #0d395e !important;
} 
.toaster_text{
    color: #ffffff;
}

.toast

